// src/api/NotificationsApi.js
import { get } from './HttpClient';

function toQuery(params = {}) {
  const q = new URLSearchParams();
  Object.entries(params).forEach(([k, v]) => {
    if (v === undefined || v === null || v === '') return;
    q.append(k, String(v));
  });
  const s = q.toString();
  return s ? `?${s}` : '';
}

/**
 * ✅ 명세 우선: GET /alerts?page&size&from&to&level&keyword
 * ⛑️ 백엔드 미구현이면 fallback: GET /logs/recent?limit=
 */
export async function fetchNotifications({
  page = 1,
  size = 50,
  from,
  to,
  level,
  keyword,
} = {}) {
  try {
    return await get(
      `/alerts${toQuery({ page, size, from, to, level, keyword })}`
    );
  } catch (e) {
    // fallback: 기존 구현 (/logs/recent)
    // alerts가 아직 없으면 여기로 들어오는 게 정상
    const limit = size;
    return get(`/logs/recent?limit=${limit}`);
  }
}

/**
 * ✅ 명세: GET /alerts/{id}
 * ⛑️ 미구현이면 null 반환(상세는 목록 state로 진입 권장)
 */
export async function fetchNotificationById(id) {
  try {
    return await get(`/alerts/${id}`);
  } catch (e) {
    return null;
  }
}

/**
 * ✅ 명세: GET /alerts/stats?range=daily|weekly&from&to
 * ⛑️ 미구현이면 null
 */
export async function fetchNotificationStats({ range = 'daily', from, to } = {}) {
  try {
    return await get(`/alerts/stats${toQuery({ range, from, to })}`);
  } catch (e) {
    return null;
  }
}
